typedef struct {size_t active,peak;int creates,reads,fail,fail_at;} NativeF16Fake;
typedef struct {uint16_t *packed;size_t bytes;} NativeF16FakeWeight;
static void *native_f16_fake_create(void *context,const BnGPUF16RowsPlan *plan) {
    NativeF16Fake *f=context;f->creates++;if(f->fail||(f->fail_at&&f->creates==f->fail_at))return NULL;size_t n=(size_t)plan->rows*plan->cols,tile=(size_t)(plan->rows<32?plan->rows:32)*plan->cols;assert(plan->device_budget_bytes>=n*2+tile*2&&plan->host_budget_bytes>=tile*2);NativeF16FakeWeight *w=calloc(1,sizeof(*w));assert(w);w->bytes=n*2;w->packed=malloc(w->bytes);uint16_t *buffer=malloc(tile*2);assert(w->packed&&buffer);f->active+=w->bytes+tile*2;if(f->active>f->peak)f->peak=f->active;
    for(int row=0;row<plan->rows;){int count=plan->rows-row;if(count>32)count=32;f->reads++;if(plan->read_rows(plan->source,row,count,buffer,tile)){f->active-=w->bytes+tile*2;free(buffer);free(w->packed);free(w);return NULL;}for(int i=0;i<count;i++)for(int j=0;j<plan->cols;j++)w->packed[(size_t)j*plan->rows+row+i]=buffer[(size_t)i*plan->cols+j];row+=count;}
    f->active-=tile*2;free(buffer);return w;
}
static void native_f16_fake_destroy(void *context,void *handle) {
    NativeF16Fake *f=context;NativeF16FakeWeight *w=handle;f->active-=w->bytes;free(w->packed);free(w);
}
